    Lemma susp_fin : forall s ps errv1 mo mc (r : rv) Fx j16 mw bw ew xg ng j6 fsv (q ret : Z),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nst0 s ps errv1 mc -> psOK ps -> stk rsegs mc lo (bv_unsigned spw) ->
      nframe mc spw j16 mw bw ew xg ng j6 fsv s4 s3 s2 s1 s0 ra ->
      (ret = 0x61dd8 \/ ret = 0x61e38) ->
      bregs r -> rra r = Z_to_bv 64 ret -> ra0 r = a0 -> ra1 r = Z_to_bv 64 q -> p <= q <= e ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x60558) fc None mc (seg_rom rsegs)) mo).
