    Ltac parser_tail tr NUM ECC STZ SCR MOREC ENDC NB NBP OPT DEPC LITC DRANGE :=
      split; [destruct NUM as (num & Ln & Rn); exists num; split; [exact Ln|]; tr Rn|];
      split; [destruct ECC as (e1 & e2 & e3 & Re & Hiff & Hne1); exists e1, e2, e3; split; [tr Re| split; [exact Hiff| exact Hne1]]|];
      split; [tr STZ|];
      split; [destruct SCR as (sc & Ls & Rs); exists sc; split; [exact Ls|]; tr Rs|];
      split; [destruct MOREC as (dn & cl & p5 & Lp & Rm); exists dn, cl, p5; split; [exact Lp|]; tr Rm|];
      split; [tr ENDC|];
      split; [destruct NB as (nb & Lb & Rb); exists nb; split; [exact Lb|]; tr Rb|];
      split; [tr NBP|];
      split; [destruct OPT as (pd2 & OPT'); exists pd2; tr OPT'|];
      split; [tr DEPC|];
      split; [destruct LITC as (j8x & Lj8 & Rl); exists j8x; split; [exact Lj8|]; tr Rl|];
      exact DRANGE.
    (* [comment removed for export] *)
    (* [comment removed for export] *)
    Lemma ufd_fin : forall s ps errv1 mo mc (r : rv) Fx fcx j16 mw bw ew xg ng j6 fsv (p' : Z) (pbk : bptr) (Bb cap : Z) (items : list vsitem),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nst0 s ps errv1 mc -> psOK ps -> stk rsegs mc lo (bv_unsigned spw) -> frm0 fcx ->
      nframe mc spw j16 mw bw ew xg ng j6 fsv s4 s3 s2 s1 s0 ra ->
      ps_vs ps = mkVS (Some (pbk, Bb, 24 * cap)) cap items 0 (pa + 280) -> Z.of_nat (length items) < cap ->
      bregs r -> rs1 r = Z_to_bv 64 p' -> ra0 r = Z_to_bv 64 (Bb + 24 * Z.of_nat (length items)) -> p < p' <= e ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x61af8) fcx None mc (seg_rom rsegs)) mo).
