    Lemma ufi_fin : forall s ps errv1 mo mc (r : rv) Fx fcx j16 mw bw ew xg ng j6 fsv (pw : word) (p' : Z) (pbk : bptr) (Bb cap : Z) (items : list vsitem),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nst0 s ps errv1 mc -> psOK ps -> stk rsegs mc lo (bv_unsigned spw) -> frm0 fcx ->
      nframe mc spw j16 mw bw ew xg ng j6 fsv s4 s3 s2 s1 s0 ra ->
      ps_vs ps = mkVS (Some (pbk, Bb, 24 * cap)) cap items 0 (pa + 280) -> Z.of_nat (length items) < cap ->
      bregs r -> rs1 r = Z_to_bv 64 p' -> ra1 r = Z_to_bv 64 (Bb + 24 * Z.of_nat (length items)) -> rs2 r = pw -> p < p' <= e ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x617dc) fcx None mc (seg_rom rsegs)) mo).
