    (* [comment removed for export] *)
    Ltac nsx NS ST INP :=
      first [ lazymatch goal with |- hs_SR _ _ (mkCfg (MS _ _ _ _ _ ?m1 _) _) =>
                match goal with Hm : munch _ _ m1 |- _ =>
                  destruct (seg_frame _ _ _ _ _ _ NS ST INP Hm ltac:(first [apply sub_96; lia | apply sub_nil]) ltac:(assumption) ltac:(assumption)) as (NSx & STx & INPx)
                end end
            | pose proof NS as NSx; pose proof ST as STx; pose proof INP as INPx ].
    (* [comment removed for export] *)
    Ltac nframe_x FR :=
      first [ lazymatch goal with |- hs_SR _ _ (mkCfg (MS _ _ _ _ _ ?m1 _) _) =>
                match goal with Hf : rw_cells _ m1 (bv_unsigned spw) _ |- _ => pose proof (Hf : nframe m1 spw _ _ _ _ _ _ _ _ s4 s3 s2 s1 s0 ra) as FRx end end
            | pose proof FR as FRx ].
    (* [comment removed for export] *)
    Ltac frame_to m2 XP2 FRx FR2 :=
      lazymatch type of FRx with nframe _ _ ?a ?b ?c ?d ?e0 ?f ?g0 ?h _ _ _ _ _ _ =>
        assert (FR2 : nframe m2 spw a b c d e0 f g0 h s4 s3 s2 s1 s0 ra)
          by (unfold nframe; eapply xpres_rw_cells; [exact XP2| exact FRx|]; split; [left; lia|]; unfold vs_X;
              constructor; [cbn [fst snd cells_size csize Nat.add]; unfold pa in *; lia| constructor])
      end.
