    Lemma finp_fin : forall s ps errv1 mo mc (r : rv) Fx j16 mw mcw bcw (bias expo xn : Z) j6 fsv (p' : Z),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      nframe mc spw j16 mcw bcw (Z_to_bv 64 expo) (b8 xn) (b8 1) j6 fsv s4 s3 s2 s1 s0 ra ->
      0 <= expo < 2^31 -> - 2^31 < bias < 2^31 -> 0 <= xn <= 1 -> (xn = 1 -> - 2^31 <= bias - expo) -> (xn = 0 -> bias + expo < 2^31) ->
      bregs r -> rs1 r = Z_to_bv 64 p' -> ra0 r = mw -> ra2 r = Z_to_bv 64 bias -> p < p' <= e ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x61a44) fc None mc (seg_rom rsegs)) mo).
