    Ltac xendc_leaves KR MP NSx PSI STx INPx FR FRX BR Rs1 Ra0 QR s ps errv1 mo mc Fx j16 mw mcw bias xn j6 fsv q :=
      lazymatch goal with
      | |- hs_SR _ _ (mkCfg (MS _ _ (Z_to_bv 64 0x61c38) _ _ _ _) _) =>
          eapply (fail_fin s ps errv1 mo _ _ Fx j16 _ _ _ _ _ j6 fsv _ 4);
            [exact KR| exact MP| apply nst0_of; exact NSx| exact PSI| exact STx| exact FR| bregs_of BR| eassumption| eassumption| eassumption| eassumption| lia| lia| lia]
      | |- hs_SR _ _ (mkCfg (MS _ _ (Z_to_bv 64 0x61a44) _ _ _ ?m1) _) =>
          first [ eapply (finp_fin s ps errv1 mo mc _ Fx j16 mw mcw (Z_to_bv 64 bias) bias 2147483647 xn j6 fsv q);
                    [exact KR| exact MP| exact NSx| exact PSI| exact STx| exact INPx| exact FRX| lia| lia| lia| lia| lia| bregs_of BR| reg_via Rs1| reg_via Ra0| eassumption| exact QR]
                | match goal with Hf : rw_cells _ _ (bv_unsigned spw) [CB 16 _; C8 _; C8 (Z_to_bv 64 9223372032559808512); C1 _; C1 _; CB 6 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _] |- _ =>
                    pose proof (nframe_split16 _ _ _ _ _ _ _ _ _ _ _ _ _ Hf) as FR1;
                    eapply (finp_fin s ps errv1 mo _ _ Fx j16 mw mcw (Z_to_bv 64 0) 0 2147483647 xn j6 fsv q);
                      [exact KR| exact MP| exact NSx| exact PSI| exact STx| exact INPx| exact FR1| lia| lia| lia| lia| lia| bregs_of BR| reg_via Rs1| reg_via Ra0| eassumption| exact QR] end ]
      end.
    Lemma xendc_fin : forall s ps errv1 mo mc (r : rv) Fx j16 mw mcw (bias xn : Z) j6 fsv (q : Z),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      nframe mc spw j16 mcw (Z_to_bv 64 bias) (Z_to_bv 64 (-2147483649)) (b8 xn) (b8 1) j6 fsv s4 s3 s2 s1 s0 ra ->
      - 2^31 < bias < 2^31 -> 0 <= xn <= 1 ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra3 r = Z_to_bv 64 (-2147483649) -> ra0 r = mw -> p < q <= e ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x619d0) fc None mc (seg_rom rsegs)) mo).
Proof.
