    Lemma xs_fin : forall s ps errv1 mo mc (r : rv) Fx j16 mw mcw (bias : Z) j6 fsv (q : Z),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      nframe mc spw j16 mcw (Z_to_bv 64 bias) (Z_to_bv 64 0) (b8 0) (b8 1) j6 fsv s4 s3 s2 s1 s0 ra ->
      - 2^31 < bias < 2^31 ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra0 r = mw -> p < q < e ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x618d4) fc None mc (seg_rom rsegs)) mo).
Proof.
