    Lemma frh_loop : forall (q : Z) s ps errv1 mo mc (r : rv) Fx j16 mw (bias : Z) j6 fsv,
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      nframe mc spw j16 mw (Z_to_bv 64 bias) (Z_to_bv 64 0) (b8 0) (b8 1) j6 fsv s4 s3 s2 s1 s0 ra ->
      - 2^31 < bias <= 0 ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 q -> ra0 r = mw -> ra2 r = Z_to_bv 64 bias ->
      ra3 r = Z_to_bv 64 9 -> ra4 r = Z_to_bv 64 2 -> ra5 r = Z_to_bv 64 (-2147483648) -> ra6 r = Z_to_bv 64 10 ->
      p < q < e ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x6174c) fc None mc (seg_rom rsegs)) mo).
Proof.
