    Lemma bigl_loopn : forall (n : nat) (k q0 : Z) s ps errv1 mo mc (r : rv) Fx j16 mw bw (bias : Z) j6 fsv,
      (Z.to_nat (e - (q0 + k + 1)) <= n)%nat ->
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      nframe mc spw j16 mw bw (Z_to_bv 64 0) (b8 0) (b8 1) j6 fsv s4 s3 s2 s1 s0 ra ->
      1 <= bias <= 2147483646 ->
      bregs r -> ra1 r = Z_to_bv 64 q0 -> ra5 r = Z_to_bv 64 k -> rs1 r = Z_to_bv 64 (q0 + k + 1) -> ra2 r = Z_to_bv 64 bias -> ra4 r = Z_to_bv 64 bias -> ra0 r = mw ->
      ra7 r = Z_to_bv 64 9 -> rt0 r = Z_to_bv 64 2147483647 -> rt1 r = Z_to_bv 64 2 ->
      2 <= q0 -> 0 <= k -> p < q0 -> q0 + k + 1 < e ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x615b8) fc None mc (seg_rom rsegs)) mo).
