    Lemma bigl_loop : forall (k q0 : Z) s ps errv1 mo mc (r : rv) Fx j16 mw bw (bias : Z) j6 fsv,
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      nframe mc spw j16 mw bw (Z_to_bv 64 0) (b8 0) (b8 1) j6 fsv s4 s3 s2 s1 s0 ra ->
      1 <= bias <= 2147483646 ->
