    (* [comment removed for export] *)
    Lemma acd2_fin : forall s ps errv1 mo mc (r : rv) Fx j16 j6 fsv mv (q nd1 nd2 : Z),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      nframe mc spw j16 mv (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 1) j6 fsv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> rs2 r = Z_to_bv 64 nd1 -> ra0 r = Z_to_bv 64 nd2 ->
      p + 1 < q -> q + 17 <= e -> 0 <= nd1 <= 16 -> 0 <= nd2 <= 16 ->
