    Lemma acd_fin : forall s ps errv1 mo mc (r : rv) Fx j16 j6 fsv mw (q nd : Z),
      hs_KREL H s mo -> hs_MPRES H mo0 mo -> nstand H E s REST ps B errv1 tp g G pa (bv_unsigned sp) m0 mc -> psOK ps ->
      stk rsegs mc lo (bv_unsigned spw) -> bytes_at rsegs mc p0 ibs ->
      nframe mc spw j16 mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 1) j6 fsv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> rs3 r = Z_to_bv 64 (q + -1) -> ra0 r = Z_to_bv 64 nd -> p < q -> q + 33 <= e -> 0 <= nd <= 16 ->
      hs_SR H POST (mkCfg (MS (mkRr r) Fx (Z_to_bv 64 0x616a4) fc None mc (seg_rom rsegs)) mo).
Proof.
